def dihedral(pts,H,W):
    res={}
    res['id']={(i,j) for i,j in pts}
    res['fH']={(i,W-1-j) for i,j in pts}
    res['fV']={(H-1-i,j) for i,j in pts}
    res['fHV']={(H-1-i,W-1-j) for i,j in pts}
    res['T']={(j,i) for i,j in pts}
    res['TfH']={(j,W-1-i) for i,j in pts}
    res['TfV']={(H-1-j,i) for i,j in pts}
    res['TfHV']={(H-1-j,W-1-i) for i,j in pts}
    return res
